import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Lab 4 · A vertical slice","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab-4-a-vertical-slice.md","filePath":"labs/lab-4-a-vertical-slice.md","lastUpdated":null}'),i={name:"labs/lab-4-a-vertical-slice.md"};function s(r,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="lab-4-·-a-vertical-slice" tabindex="-1">Lab 4 · A vertical slice <a class="header-anchor" href="#lab-4-·-a-vertical-slice" aria-label="Permalink to &quot;Lab 4 · A vertical slice&quot;">​</a></h1><p><strong>Deliverable:</strong> a pull request: contract change, tests, deployment, interface · <strong>Time:</strong> two hours, and it will not all fit</p><p>The first lab where you change a contract. A full stack dApp developer is not someone who writes Solidity <em>or</em> React; it is someone who can take a requirement through both and know which side each problem belongs on.</p><h2 id="the-requirement" tabindex="-1">The requirement <a class="header-anchor" href="#the-requirement" aria-label="Permalink to &quot;The requirement&quot;">​</a></h2><blockquote><p>Tenants who have paid every month should be able to renew a lease without repaying the deposit. At the moment the lease ends, the deposit is settled, and a renewal means finding that money again — which for many tenants is the reason they cannot move and the reason they cannot stay.</p></blockquote><p>That is the requirement as a product owner would give it: a real problem, no implementation. The design is yours.</p><h2 id="your-job" tabindex="-1">Your job <a class="header-anchor" href="#your-job" aria-label="Permalink to &quot;Your job&quot;">​</a></h2><ol><li><strong>Design it.</strong> Write the design in the PR description <em>before</em> the code: what changes in <code>RentEscrow</code>, what new state, who can call what, and what the new failure cases are.</li><li><strong>Implement it</strong> in <code>contracts/src/RentEscrow.sol</code>.</li><li><strong>Test it</strong> in <code>contracts/test/Housing.t.sol</code>.</li><li><strong>Deploy it</strong> — update the deployment script, run <code>npm run sync-abi</code>, and note in the PR what a real redeploy of this contract would owe (there are two follow-ups, and both fail silently; lab 1&#39;s reading should have shown you where they are documented).</li><li><strong>Build the interface</strong> in <code>Housing.jsx</code>.</li></ol><h2 id="constraints-that-are-not-negotiable" tabindex="-1">Constraints that are not negotiable <a class="header-anchor" href="#constraints-that-are-not-negotiable" aria-label="Permalink to &quot;Constraints that are not negotiable&quot;">​</a></h2><ul><li><strong>The deposit stays where neither party controls it.</strong> A renewal that pays the deposit out and takes it back is not a renewal; it is two transactions and a window where the tenant&#39;s money is somewhere it should not be.</li><li><strong>Neither party can renew alone.</strong> Work out what &quot;agreement&quot; means on chain, and implement it. There is more than one right answer; there are many wrong ones.</li><li><strong>Existing leases keep working.</strong> Your change must not alter the behaviour of a lease already in progress. Every existing test must still pass, unchanged.</li><li><strong>Durations stay bounded.</strong> The contract&#39;s <code>MIN_TERM</code> and <code>MAX_TERM</code> exist so the same code works for a lab and a homework week. Do not bypass them.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>[ ] A design section in the PR that a reviewer could have implemented from.</li><li>[ ] The contract compiles optimized and its deployed size is reported (<code>forge build --sizes</code>).</li><li>[ ] New tests cover: the happy path, each party trying to renew alone, renewing a lease that has already ended, renewing one that was claimed against, and at least one fuzz test over the amounts or durations.</li><li>[ ] <strong>All existing Housing tests pass unchanged.</strong> If you had to change one, the PR explains why — and &quot;it was in the way&quot; is a finding about your design.</li><li>[ ] <code>npm run sync-abi</code> run and the result committed.</li><li>[ ] The interface offers renewal only when it is actually possible, and says why when it is not.</li><li>[ ] CI green.</li></ul><h2 id="deployment-notes" tabindex="-1">Deployment notes <a class="header-anchor" href="#deployment-notes" aria-label="Permalink to &quot;Deployment notes&quot;">​</a></h2><p>You are changing a deployed contract. In your PR, answer:</p><ul><li>Existing leases live in the <strong>old</strong> contract. What happens to them when you deploy the new one? Is that acceptable, and who decides?</li><li>What would the migration be if this were real money?</li></ul><p>This is the question that separates a student exercise from engineering. Most on-chain code cannot be changed after deployment, so &quot;we will fix it in the next release&quot; is not available, and the design has to carry that weight from the start.</p><h2 id="common-ways-this-goes-wrong" tabindex="-1">Common ways this goes wrong <a class="header-anchor" href="#common-ways-this-goes-wrong" aria-label="Permalink to &quot;Common ways this goes wrong&quot;">​</a></h2><ul><li><strong>A renewal that pays out and re-collects.</strong> Re-read the first constraint.</li><li><strong>A one-sided renew.</strong> If the landlord can extend a lease unilaterally, you have built a trap. If the tenant can, you have built a different one.</li><li><strong>Timestamp arithmetic that overflows or wraps.</strong> <code>endsAt + term</code> is a <code>uint64</code>. Prove it is safe or make it safe.</li><li><strong>Silently changing an existing test to make it pass.</strong> A reviewer will diff the test file first. So will an employer.</li><li><strong>Forgetting <code>sync-abi</code>.</strong> The app builds against a stale ABI and the new function is simply absent, with no error anywhere. CI catches this; notice that it does.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>No changes to <code>PropertyDeeds</code>. No new tokens. No UI redesign — add to the existing card.</p><h2 id="hand-in" tabindex="-1">Hand in <a class="header-anchor" href="#hand-in" aria-label="Permalink to &quot;Hand in&quot;">​</a></h2><ol><li>The PR with its design section, CI green, reviewed and approved.</li><li>Your review of someone else&#39;s PR. Read their tests before their contract, and check whether both parties really have to agree.</li><li>An incident write-up. This is the lab where something will break — a stale ABI, a missing role, a deploy that half-worked. Write it up properly.</li></ol>',22)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
